import { test } from "node:test";
import assert from "node:assert";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { isOwned, renderIgnore, OWNER_PREFIX } from "../src/search-ignore/ignoreFile";
import { pickProbe } from "../src/search-ignore/probe";

test("renderIgnore: 머리 3줄, system 그대로, user는 중복 빼고 뒤에", () => {
  const out = renderIgnore(".p4ignore", ["Intermediate/", "Saved/Autosaves/"], ["Temp/", "Intermediate/", "Temp/"]);
  assert.strictEqual(
    out,
    [
      "# generated by /dev-workflow:search-ignore — do not edit",
      "# 직접 고치면 다음 실행 때 사라집니다. .claude/ignore.yaml의 user 부분을 고친 뒤 /dev-workflow:search-ignore를 다시 실행하세요",
      "# source: .p4ignore",
      "Intermediate/",
      "Saved/Autosaves/",
      "Temp/",
      "",
    ].join("\n"),
  );
});

test("isOwned: BOM과 CR을 걷고 첫 줄 앞부분", () => {
  assert.ok(isOwned("﻿" + OWNER_PREFIX + " — do not edit\r\nX/\r\n"));
  assert.ok(isOwned(OWNER_PREFIX + " — v2 다른 꼬리\n"));
  assert.ok(!isOwned("Intermediate/\n"));
  assert.ok(!isOwned(""));
});

test("pickProbe: 텍스트 파일의 특수문자 없는 긴 줄, 바이너리는 건너뜀", () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "si-probe-"));
  fs.mkdirSync(path.join(root, "GW/Intermediate/a"), { recursive: true });
  fs.writeFileSync(path.join(root, "GW/Intermediate/a/0.bin"), Buffer.from([0, 1, 2, 65, 66]));
  fs.writeFileSync(path.join(root, "GW/Intermediate/a/1.h"), "#pragma once\nshort\nvoid Foo(int x); // skip\nUCLASS generated body for GWItemCoreRuntime module\n");
  assert.deepStrictEqual(pickProbe(root, "GW/Intermediate"), {
    file: "GW/Intermediate/a/1.h",
    text: "UCLASS generated body for GWItemCoreRuntime module",
  });
});

test("pickProbe: 고를 줄이 없으면 null", () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "si-probe-"));
  fs.mkdirSync(path.join(root, "Saved"), { recursive: true });
  fs.writeFileSync(path.join(root, "Saved/x.txt"), "a.b\n");
  assert.strictEqual(pickProbe(root, "Saved"), null);
});
